changeSet.rollback:
create or alter procedure [metrics].[LoadFromStaging] as begin set nocount on;
begin try
update T set T.Archived = 0 from metrics.StagingScoreItem T inner join ( select distinct AssetUid, MetricAssetUid, EffectiveDate from metrics.StagingScoreItem where Archived = 0 ) S on S.AssetUid = T.AssetUid and S.MetricAssetUid = T.MetricAssetUid and S.EffectiveDate < T.EffectiveDate and T.Archived = 1;
declare @min_date date, @max_date date, @current_date date, @run_date datetime select @min_date = min(EffectiveDate), @max_date = max(EffectiveDate) from metrics.StagingScoreItem where Archived = 0
set @current_date = @min_date set @run_date = getutcdate();
drop table if exists #assets; create table #assets (AssetTypeUid uniqueidentifier not null, [Type] varchar(50), TypeID int, AssetUid uniqueidentifier not null, [Object] varchar(50), ObjectID int, ScoreType int); CREATE CLUSTERED INDEX CIX_TempAssets ON #assets ([AssetTypeUid]);
drop table if exists #priorResults; create table #priorResults ( AssetUid uniqueidentifier not null, MetricAssetUid uniqueidentifier not null, [Value] bit not null, EffectiveDate date ); CREATE NONCLUSTERED INDEX IX_TempPriorResults_Asset_Metric ON #priorResults (AssetUid, MetricAssetUid);
drop table if exists #maxEffectiveMetrics; create table #maxEffectiveMetrics ( MetricAssetUid uniqueidentifier not null, EffectiveDate date ); CREATE CLUSTERED INDEX CIX_TempMaxEffectiveMetric ON #maxEffectiveMetrics (MetricAssetUid, EffectiveDate);
drop table if exists #step1; create table #step1 ( AssetUid uniqueidentifier not null, MetricAssetUid uniqueidentifier not null, ParentUid uniqueidentifier null, IsGroup bit not null, [Weight] decimal(5,3) not null, [Value] bit not null, ScoreType int not null ); CREATE NONCLUSTERED INDEX IX_TempStep1_Asset_Metric_EffectiveDate ON #step1 (AssetUid, MetricAssetUid); CREATE NONCLUSTERED INDEX IX_TempStep1_Asset_ParentMetric_EffectiveDate ON #step1 (AssetUid, ParentUid);
drop table if exists #step2; create table #step2 ( AssetUid uniqueidentifier not null, MetricAssetUid uniqueidentifier not null, ParentUid uniqueidentifier null, IsGroup bit not null, IsRelevant bit, [Weight] decimal(5,3) not null, [Value] bit not null, [Level] int null, AdjustedWeight decimal(6,4) null, Score decimal(6,4) null, ScoreType int not null ); CREATE NONCLUSTERED INDEX IX_TempStep2_Metric_IsGroup_Level ON #step2 (MetricAssetUid, IsGroup, [Level]); CREATE NONCLUSTERED INDEX IX_TempStep2_Parent_Level_IsRelevant ON #step2 (ParentUid, [Level], IsRelevant);
drop table if exists #conditionChecks; create table #conditionChecks ( AssetUid uniqueidentifier, MetricAssetUid uniqueidentifier, EffectiveDate date ); CREATE CLUSTERED INDEX CIX_TempConditionChecks ON #conditionChecks (AssetUid, MetricAssetUid, EffectiveDate);
while @current_date <= @max_date begin truncate table #step2; truncate table #step1; truncate table #maxEffectiveMetrics; truncate table #priorResults; truncate table #assets; truncate table #conditionChecks;
update metrics.StagingScoreItem set Processing = 1 where Archived = 0 and EffectiveDate = @current_date;
insert into #assets select T.[Uid], T.Object, T.ObjectID, A.[Uid], A.Object, A.ObjectID, R.ScoreType from metrics.StagingScoreItem R inner join dbo.Asset A on A.[uid] = R.AssetUid inner join dbo.AssetType T on T.ID = A.AssetTypeID where R.Processing = 1 and R.EffectiveDate = @current_date group by T.[Uid], T.Object, T.ObjectID, A.[Uid], A.Object, A.ObjectID, R.ScoreType;
insert into #maxEffectiveMetrics select AssetUid, max(EffectiveDate) as EffectiveDate from metrics.AssetVersion where EffectiveDate <= @current_date group by AssetUid;
insert into #priorResults select SI.AssetUid, SI.MetricAssetUid, SI.Value, SI.EffectiveDate from metrics.ScoreItem SI inner join ( select SI.AssetUid, SI.MetricAssetUid, max(SI.EffectiveDate) as EffectiveDate from metrics.ScoreItem SI inner join metrics.Asset A on A.[Uid] = SI.MetricAssetUid and A.State = 1 inner join metrics.Allocation Al on Al.Uid = A.AllocationUid inner join #assets E on E.AssetTypeUid = Al.AssetTypeUid and E.AssetUid = SI.AssetUid and SI.EffectiveDate <= @current_date and E.ScoreType = Al.ScoreType group by SI.AssetUid, SI.MetricAssetUid ) MSI on MSI.AssetUid = SI.AssetUid and MSI.MetricAssetUid = SI.MetricAssetUid and MSI.EffectiveDate = SI.EffectiveDate;
insert into #conditionChecks select A.AssetUid, M.Uid as MetricAssetUid, MaxE.EffectiveDate from #assets A left join metrics.Allocation Al on Al.AssetTypeUid = A.AssetTypeUid and Al.ScoreType = A.ScoreType inner join metrics.Asset M on M.AllocationUid = Al.Uid and M.IsGroup = 0 and M.State = 1 inner join #maxEffectiveMetrics MaxE on MaxE.MetricAssetUid = M.Uid inner join FieldType FT on FT.Object = A.[Type] and FT.ObjectID = A.TypeID and FT.[Type] in ('Boolean', 'Date', 'DateTime', 'Decimal', 'Html', 'Link', 'Lookup', 'Number', 'Percentage', 'Text') left join Field F on F.FieldTypeID = FT.ID and F.ObjectType = A.Object and F.ObjectID = A.ObjectID inner join metrics.AssetVersion MV on MV.AssetUid = M.[Uid] and MV.EffectiveDate = MaxE.EffectiveDate left join metrics.AssetVersionCondition C on C.AssetVersionUid = M.[Uid] left join metrics.AssetVersionConditionItem CI on CI.AssetVersionConditionUid = C.Uid and CI.ConditionFieldTypeID = FT.ID left join metrics.AssetVersionConditionItemValue CIV on CIV.Uid = CI.Uid left join ( select A.AssetUid, M.Uid as MetricAssetUid, MV.EffectiveDate from #assets A inner join dbo.FieldType FT on FT.Object = A.[Type] and FT.ObjectID = A.TypeID and FT.[Type] in ('Boolean', 'Date', 'DateTime', 'Decimal', 'Html', 'Link', 'Lookup', 'Number', 'Percentage', 'Text') left join dbo.Field F on F.FieldTypeID = FT.ID and F.ObjectType = A.Object and F.ObjectID = A.ObjectID inner join metrics.Allocation Al on Al.AssetTypeUid = A.AssetTypeUid and Al.ScoreType = A.ScoreType inner join metrics.Asset M on M.AllocationUid = Al.Uid and M.IsGroup = 0 and M.State = 1 inner join #maxEffectiveMetrics MaxE on MaxE.MetricAssetUid = M.Uid inner join metrics.AssetVersion MV on MV.AssetUid = M.[Uid] and MV.EffectiveDate = MaxE.EffectiveDate inner join metrics.AssetVersionCondition C on C.AssetVersionUid = MV.[Uid] inner join metrics.AssetVersionConditionItem CI on CI.AssetVersionConditionUid = C.Uid and CI.ConditionFieldTypeID = FT.ID inner join metrics.AssetVersionConditionItemValue CIV on CIV.Uid = CI.Uid where metrics.CompareConditionValueToFieldValue(FT.[Type], CI.Operator, CIV.[Value], coalesce(F.Value, FT.DefaultValue)) = 0 group by A.AssetUid, M.Uid, MV.EffectiveDate ) B on B.AssetUid = A.AssetUid and B.MetricAssetUid = M.Uid and B.EffectiveDate = MV.EffectiveDate where ( ( C.Uid is not null and F.ID is not null and metrics.CompareConditionValueToFieldValue(FT.[Type], CI.Operator, CIV.[Value], coalesce(F.Value, FT.DefaultValue)) = 1 ) or C.Uid is null ) and B.AssetUid is null group by A.AssetUid, M.Uid, MaxE.EffectiveDate;
insert into #step1 select E.AssetUid, A.[Uid], A.ParentUid, A.IsGroup, V.Weight, coalesce(S.Result, P.Value, 0) as Value, coalesce(S.ScoreType, 1) as ScoreType from metrics.AssetVersion V inner join metrics.Asset A on A.[Uid] = V.[AssetUid] inner join metrics.Allocation Al on Al.Uid = A.AllocationUid inner join #assets E on E.AssetTypeUid = Al.AssetTypeUid and A.State = 1 and E.ScoreType = Al.ScoreType inner join #maxEffectiveMetrics MV on MV.MetricAssetUid = A.[Uid] left join #conditionChecks C on C.AssetUid = E.AssetUid and C.MetricAssetUid = MV.MetricAssetUid and C.EffectiveDate = MV.EffectiveDate left join metrics.StagingScoreItem S on S.AssetUid = E.AssetUid and S.MetricAssetUid = V.AssetUid and S.EffectiveDate = @current_date left join #priorResults P on P.AssetUid = E.AssetUid and P.MetricAssetUid = A.Uid where V.EffectiveDate = MV.EffectiveDate and ( (C.AssetUid is null and A.IsGroup = 1) or (C.AssetUid is not null and A.IsGroup = 0) );
with MetricHierarchy as ( select AssetUid, MetricAssetUid, ParentUid, IsGroup, Weight, Value, 1 as [Level], ScoreType from #step1 where ParentUid is null union all select c.AssetUid, c.MetricAssetUid, c.ParentUid, c.IsGroup, c.Weight, c.Value, h.[Level] + 1 as [Level], c.ScoreType from #step1 c inner join MetricHierarchy h on h.AssetUid = c.AssetUid and h.MetricAssetUid = c.[ParentUid] )
insert into #step2 (AssetUid, MetricAssetUid, ParentUid, IsGroup, Weight, [Value], [Level], ScoreType) select * from MetricHierarchy order by [Level];
update #step2 set IsRelevant = 1 where IsGroup = 0;
declare @maxLevel int select @maxLevel = max(Level) from #step2 while @maxLevel >= 1 begin update T set T.IsRelevant = case when [RelevantItemCount] > 0 then 1 else 0 end from #step2 T cross apply ( select count(1) as [RelevantItemCount] from #step2 where ParentUid = T.MetricAssetUid and AssetUid = T.AssetUid and [Level] = @maxLevel + 1 and IsRelevant = 1 ) S where T.IsGroup = 1 and T.[Level] = @maxLevel
set @maxLevel = @maxLevel - 1 end;
update T set T.AdjustedWeight = IIF(T.Weight = 0, 1, T.Weight) / IIF(S.Weight = 0, 1, S.Weight) from #step2 T outer apply ( select sum(Weight) Weight from #step2 where AssetUid = T.AssetUid and ( (ParentUid = T.ParentUid) or (ParentUid is null and T.ParentUid is null) ) and IsRelevant = 1 ) S;
update #step2 set Score = case [Value] when 1 then AdjustedWeight else 0 end where IsGroup = 0;
update #step2 set Score = null where IsGroup = 1;
declare @stopLevel int = 1, @currentLevel int select @currentLevel = max([Level]) from #step2;
while @currentLevel >= @stopLevel begin update T set T.Score = S.Score*AdjustedWeight from #step2 T cross apply ( select sum(coalesce(Score, AdjustedWeight)) as Score from #step2 where ParentUid = T.MetricAssetUid and AssetUid = T.AssetUid and [Level] = @currentLevel+1 ) S where T.[Level] = @currentLevel and T.IsGroup = 1
set @currentLevel = @currentLevel - 1 end;
update #step2 set Score = case when Value = 1 then AdjustedWeight else 0 end where Score is null;
merge metrics.Score as T using ( select AssetUid, case when round(sum(Score), 3) > 1 then 1 else round(sum(Score), 3) end as Value, ScoreType from #step2 where [Level] = 1 and Score is not null and IsRelevant = 1 group by AssetUid, ScoreType ) S on ( (T.AssetUid = S.AssetUid and T.EffectiveDate <= @current_date and T.EndDate is null and T.[Value] = S.[Value] and T.ScoreType = S.ScoreType) or (T.AssetUid = S.AssetUid and T.EffectiveDate = @current_date and T.ScoreType = S.ScoreType) ) when matched then update set T.Value = S.Value, T.RunDate = @run_date when not matched by target then insert (AssetUid, EffectiveDate, Value, ScoreType, RunDate) values (S.AssetUid, @current_date, S.Value, S.ScoreType, @run_date);
--set end date for previous score items update M set M.EndDate = R.EffectiveDate from [metrics].[Score] M cross apply ( select top 1 R.EffectiveDate from [metrics].[Score] R inner join #step2 S on S.AssetUid = R.AssetUid and S.IsRelevant = 1 and S.ScoreType = R.ScoreType and S.[Level] = 1 where R.EffectiveDate <> M.EffectiveDate and R.AssetUid = M.AssetUid and R.EffectiveDate > M.EffectiveDate and R.ScoreType = M.ScoreType order by R.EffectiveDate asc ) R;
merge metrics.ScoreItem as T using ( select distinct s2.AssetUid, s2.MetricAssetUid, s2.Value, s2.AdjustedWeight, s2.ScoreType from #step2 s2 inner join metrics.Asset A on A.[uid] = s2.MetricAssetUid inner join metrics.Allocation Al on Al.Uid = A.AllocationUid and Al.ScoreType = s2.ScoreType ) S on ( (T.AssetUid = S.AssetUid and T.MetricAssetUid = S.MetricAssetUid and T.EffectiveDate <= @current_date and T.EndDate is null and T.[Value] = S.[Value]) or (T.AssetUid = S.AssetUid and T.MetricAssetUid = S.MetricAssetUid and T.EffectiveDate = @current_date) ) when matched then update set T.AdjustedWeight = S.AdjustedWeight, T.Value = S.Value, T.UpdatedOn = getutcdate(), T.RunDate = @run_date when not matched by target then insert (AssetUid, MetricAssetUid, EffectiveDate, UpdatedOn, Value, AdjustedWeight, RunDate) values (S.AssetUid, S.MetricAssetUid, @current_date, getutcdate(), S.Value, S.AdjustedWeight, @run_date);
--set end date for previous score items update M set M.EndDate = R.EffectiveDate from [metrics].[ScoreItem] M inner join metrics.Asset A on A.[uid] = M.MetricAssetUid cross apply ( select top 1 R.EffectiveDate from [metrics].[ScoreItem] R inner join metrics.Asset AR on AR.[uid] = R.MetricAssetUid inner join #step2 S on S.AssetUid = R.AssetUid and S.MetricAssetUid = R.MetricAssetUid inner join metrics.Allocation Al on Al.Uid = AR.AllocationUid and Al.ScoreType = S.ScoreType where R.EffectiveDate <> M.EffectiveDate and R.AssetUid = M.AssetUid and R.EffectiveDate > M.EffectiveDate and R.MetricAssetUid = M.MetricAssetUid order by R.EffectiveDate asc ) R;
delete T from metrics.StagingScoreItem T inner join metrics.StagingScoreItem S on S.AssetUid = T.AssetUid and S.MetricAssetUid = T.MetricAssetUid and T.EffectiveDate = @current_date and S.EffectiveDate = T.EffectiveDate and T.Archived = 1 and S.Archived = 0 and S.Processing = 1
update metrics.StagingScoreItem set Processing = 0, Archived = 1 where EffectiveDate = @current_date and Archived = 0 and Processing = 1;
set @current_date = dateadd(day, 1, @current_date); end end try begin catch throw end catch end
